/* 2) MÃ¼ÅŸteri hizmetleri talepleri (satÄ±ÅŸlardan tÃ¼retilir) */
const Talepler = []; let tNo = 1;
const KANAL = ['Telefon', 'E-posta', 'CanlÄ± destek', 'Sosyal medya'], KW = [.34, .28, .3, .08];
const pickW = (a, w) => { let x = R(), c = 0; for (let i = 0; i < a.length; i++) { c += w[i]; if (x <= c) return a[i]; } return a[a.length - 1]; };
