  pitfall: 'ABC\'yi hesaplanmÄ±ÅŸ sÃ¼tun olarak yaparsan sÄ±nÄ±flar yenileme anÄ±nda donar ve dilimleyiciye tepki vermez; Ã¶lÃ§Ã¼ olarak yaparsan dinamiktir ama eksene konamaz. Ä°kisinin de yeri vardÄ±r.',
