  pitfall: 'Segment adlarÄ±nÄ± Ã¶lÃ§Ã¼de sabit yazmak yerine RFMSegmentleri tablosundaki sÄ±rayla eÅŸleÅŸtirmek, rapordaki renk ve sÄ±ralamayÄ± tutarlÄ± tutar.',
