    ['Esneklik', 'VarsayÄ±m. GerÃ§ek projede kategori bazÄ±nda farklÄ± esneklikler bir tablodan alÄ±nabilir.'],
    ['AdetCarpani', 'Adet etkisi; MAX(0, â€¦) negatif satÄ±ÅŸÄ± engeller.'],
    ['SUMX', 'Her satÄ±ÅŸ satÄ±rÄ±nda yeni tutar = eski tutar Ã— fiyat Ã§arpanÄ± Ã— adet Ã§arpanÄ±.']
