  pitfall: 'What-if sonuÃ§larÄ±nÄ± gerÃ§ekleÅŸen deÄŸerlerle aynÄ± renkte gÃ¶sterme; senaryo olduÄŸunu baÅŸlÄ±k ve renkle belli et.',
