    ['YeniMaliyet', 'Birim maliyet deÄŸiÅŸmez, adet deÄŸiÅŸtiÄŸi iÃ§in toplam maliyet deÄŸiÅŸir.'],
    ['RETURN', 'KÃ¢r. Eksende FiyatSenaryosu[FiyatDegisimi] olunca her senaryo ayrÄ± hesaplanÄ±r.']
