    ['AyBasi', 'Ay etiketinden ayÄ±n ilk gÃ¼nÃ¼. DeÄŸiÅŸken SUMX\'in iÃ§inde, her ay iÃ§in yeniden tanÄ±mlanÄ±r.'],
    ['Kur', 'Ä°liÅŸki olmadan kur tablosundan deÄŸer bulma: iki koÅŸullu LOOKUPVALUE.'],
    ['DIVIDE', 'AyÄ±n TL satÄ±ÅŸÄ± Ã· o ayÄ±n kuru. Ã–lÃ§Ã¼ Ã§aÄŸrÄ±sÄ± baÄŸlam geÃ§iÅŸiyle yalnÄ±zca o ayÄ±n satÄ±ÅŸÄ±nÄ± verir.']
