  pitfall: 'YÄ±llÄ±k TL toplamÄ±nÄ± yÄ±llÄ±k ortalama kura bÃ¶lmek, kurun hÄ±zlÄ± deÄŸiÅŸtiÄŸi yÄ±llarda ciddi yanlÄ±ÅŸ sonuÃ§ verir; dÃ¶nÃ¼ÅŸÃ¼m iÅŸlemin yapÄ±ldÄ±ÄŸÄ± tanecikte (ay) yapÄ±lmalÄ±dÄ±r.',
